-- dados.sql — banco "saudável mas rico" para a fumaça dos audits/guards.
-- Tudo aqui deve PASSAR em todos os guards: PK em toda tabela, RLS + policy, FKs íntegras,
-- sequences alinhadas, SECURITY DEFINER com search_path seguro. Achados meramente
-- informativos (coluna PLAIN, autovacuum desligado, índice duplicado) existem de propósito
-- para os audits terem o que listar. Só cria objetos dentro do banco corrente.
\set ON_ERROR_STOP on
SET client_min_messages = warning;

CREATE TABLE public.clientes (
  id        bigserial PRIMARY KEY,
  nome      text NOT NULL,
  email     text NOT NULL UNIQUE,
  obs       text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE public.pedidos (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  cliente_id bigint NOT NULL REFERENCES public.clientes(id),
  total      numeric(12,2) NOT NULL CHECK (total >= 0),
  status     text NOT NULL DEFAULT 'aberto',
  payload    jsonb
);
CREATE TABLE public.itens (
  pedido_id bigint NOT NULL,
  seq       int    NOT NULL,
  sku       text   NOT NULL,
  PRIMARY KEY (pedido_id, seq),
  FOREIGN KEY (pedido_id) REFERENCES public.pedidos(id)
);
CREATE TABLE public.entregas (           -- FK composta
  id        serial PRIMARY KEY,
  pedido_id bigint,
  seq       int,
  FOREIGN KEY (pedido_id, seq) REFERENCES public.itens(pedido_id, seq)
);
CREATE TABLE public.eventos (
  id        bigint GENERATED BY DEFAULT AS IDENTITY,
  criado_em timestamptz NOT NULL,
  tipo      text NOT NULL,
  PRIMARY KEY (id, criado_em)
) PARTITION BY RANGE (criado_em);
CREATE TABLE public.eventos_2026_01 PARTITION OF public.eventos FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');
CREATE TABLE public.eventos_2026_02 PARTITION OF public.eventos FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');
CREATE TABLE public._interna (k text PRIMARY KEY, v text);   -- prefixo _: fora do rls-coverage
CREATE TABLE public.anexos (id serial PRIMARY KEY, conteudo oid);
CREATE TABLE public."Nome Misto" ("Id" serial PRIMARY KEY, valor int);

-- tabelas que o logical-vs-physical-drift consulta por padrão
CREATE TABLE public.contacts     (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text);
CREATE TABLE public.companies    (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text);
CREATE TABLE public.interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nota text);
CREATE TABLE public.deals        (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), valor numeric);

INSERT INTO public.clientes (nome, email, obs)
SELECT 'Cliente ' || g, 'c' || g || '@exemplo.test', repeat('x', 50) FROM generate_series(1, 2000) g;
INSERT INTO public.pedidos (cliente_id, total, payload)
SELECT 1 + (g % 2000), (g % 500)::numeric, jsonb_build_object('n', g) FROM generate_series(1, 5000) g;
INSERT INTO public.itens SELECT p.id, 1, 'SKU-' || p.id FROM public.pedidos p WHERE p.id <= 1000;
INSERT INTO public.entregas (pedido_id, seq) SELECT pedido_id, seq FROM public.itens WHERE pedido_id <= 100;
INSERT INTO public.entregas (pedido_id, seq) VALUES (NULL, NULL), (5, NULL);   -- MATCH SIMPLE: não é órfã
INSERT INTO public.eventos (criado_em, tipo)
SELECT timestamptz '2026-01-01' + (g || ' hours')::interval, 'e' FROM generate_series(1, 1000) g;
INSERT INTO public._interna VALUES ('versao', '1');
INSERT INTO public.anexos (conteudo) SELECT lo_from_bytea(0, 'conteudo'::bytea) FROM generate_series(1, 3);
INSERT INTO public."Nome Misto" (valor) SELECT g FROM generate_series(1, 10) g;
INSERT INTO public.contacts (nome)     SELECT 'c' || g FROM generate_series(1, 20) g;
INSERT INTO public.companies (nome)    SELECT 'e' || g FROM generate_series(1, 5) g;
INSERT INTO public.interactions (nota) SELECT 'i' || g FROM generate_series(1, 7) g;

CREATE FUNCTION public.normaliza(t text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT lower(btrim(t)) $$;
CREATE INDEX clientes_nome_norm_idx ON public.clientes (public.normaliza(nome));
CREATE INDEX pedidos_cliente_idx ON public.pedidos (cliente_id);
CREATE INDEX pedidos_abertos_idx ON public.pedidos (total) WHERE status = 'aberto';
CREATE INDEX pedidos_cliente_dup_idx ON public.pedidos (cliente_id);       -- duplicado de propósito (audit)
ALTER TABLE public.clientes ALTER COLUMN obs SET STORAGE PLAIN;            -- achado dos audits de TOAST
ALTER TABLE public._interna SET (autovacuum_enabled = false);              -- achado do autovacuum-audit

CREATE FUNCTION public.fn_segura_vazia() RETURNS int LANGUAGE sql SECURITY DEFINER SET search_path = '' AS 'SELECT 1';
CREATE FUNCTION public.fn_segura_catalogo() RETURNS int LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, public AS 'SELECT 1';
CREATE FUNCTION public.tg_toca() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.obs := COALESCE(NEW.obs, ''); RETURN NEW; END $$;
CREATE TRIGGER clientes_toca BEFORE INSERT OR UPDATE ON public.clientes FOR EACH ROW EXECUTE FUNCTION public.tg_toca();
CREATE SEQUENCE public.avulsa_seq;
SELECT nextval('public.avulsa_seq');
CREATE MATERIALIZED VIEW public.mv_totais AS SELECT cliente_id, sum(total) AS total FROM public.pedidos GROUP BY 1;
CREATE UNIQUE INDEX mv_totais_pk ON public.mv_totais (cliente_id);

DO $$
DECLARE t record;
BEGIN
  FOR t IN SELECT c.oid::regclass AS rel FROM pg_class c
            WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('r','p')
              AND c.relname NOT LIKE '\_%' ESCAPE '\'
  LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', t.rel);
    IF NOT EXISTS (SELECT 1 FROM pg_inherits i WHERE i.inhrelid = t.rel::oid) THEN
      EXECUTE format('CREATE POLICY leitura ON %s FOR SELECT USING (true)', t.rel);
    END IF;
  END LOOP;
END $$;

CREATE PUBLICATION pub_fixture FOR TABLE public.clientes, public.pedidos;
CREATE EXTENSION IF NOT EXISTS amcheck;
CREATE EXTENSION IF NOT EXISTS pg_visibility;
CREATE EXTENSION IF NOT EXISTS postgres_fdw;
CREATE SERVER srv_fixture FOREIGN DATA WRAPPER postgres_fdw OPTIONS (host '127.0.0.1', dbname 'inexistente');
CREATE USER MAPPING FOR CURRENT_USER SERVER srv_fixture OPTIONS (user 'leitor');
ANALYZE;
